from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature


_SIGNATURE_HEADER = "X-Webhook-Signature"
_REQUIRED_FIELDS = ("event_id", "event_type", "account_id")


def _reject(reason: str) -> dict[str, Any]:
    """Build the documented rejection response."""

    return {"status": "rejected", "reason": reason}


def _header_value(headers: Mapping[str, Any], name: str) -> Any:
    """Fetch a header, tolerating case differences in header names."""

    value = headers.get(name)
    if value is not None:
        return value
    lowered = name.lower()
    for key, candidate in headers.items():
        if isinstance(key, str) and key.lower() == lowered:
            return candidate
    return None


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event.

    The receiver is wired to a publicly exposed route (see ``deployment.json``:
    ``ingress: public`` with no authenticating middleware or relay in front),
    so every delivery must carry a valid HMAC-SHA256 signature in the
    ``X-Webhook-Signature`` header. Requests without a verifiable signature are
    rejected rather than silently accepted: there is nothing on this route that
    would distinguish an unsigned "relay-format" delivery from a forged one.
    """

    if not isinstance(request, Mapping):
        return _reject("malformed request")

    headers = request.get("headers")
    body = request.get("body")

    if not isinstance(headers, Mapping):
        return _reject("malformed request")
    if not isinstance(body, (bytes, bytearray, memoryview)):
        return _reject("malformed request")
    body = bytes(body)

    secret = os.environ.get("WEBHOOK_SECRET")
    if not secret:
        # Fail closed when the receiver is not configured with a secret.
        return _reject("missing webhook secret")

    signature = _header_value(headers, _SIGNATURE_HEADER)
    if not verify_signature(body, signature, secret):
        return _reject("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _reject("invalid json body")

    if not isinstance(event, dict):
        return _reject("malformed event")

    for field in _REQUIRED_FIELDS:
        if not isinstance(event.get(field), str):
            return _reject(f"missing or invalid field: {field}")

    # The event is appended exactly once, with its fields passed through
    # unchanged for downstream schema compatibility.
    append_event(event)
